def nib_points(style, weight):
    rx, ry, angle = ((92, 49, -32), (135, 31, -22))[style]
    a = math.radians(angle)
    base = [(-rx, 0), (-rx * 0.42, -ry), (rx * 0.7, -ry * 0.55), (rx, 0), (rx * 0.42, ry), (-rx * 0.7, ry * 0.55)]
    return [(weight * (x * math.cos(a) - y * math.sin(a)), weight * (x * math.sin(a) + y * math.cos(a))) for x, y in base]

def dot(x, y, style):
    radius = 83 if style == 0 else 95
    return Polygon([(x - radius, y - 20), (x + 20, y + radius), (x + radius, y + 15), (x - 20, y - radius)])
